        raise HTTPException(422, "本课规则模式请使用 任务：标题")
    title = data.text[3:].strip()
    if not title or len(title) > 200:
        raise HTTPException(422, "标题长度应为 1 到 200")
    return {"mode": "offline-rule", "draft": {"title": title}}


