{
  "name": "guided-react-lab",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --host 127.0.0.1 --port 5176 --strictPort",
    "build": "vite build"
  },
  "dependencies": {
    "react": "19.3.1",
    "react-dom": "19.3.1"
  },
  "devDependencies": {
    "vite": "8.3.5"
  }
}

import React, { useState } from 'react'
import { createRoot } from 'react-dom/client'
function App() {
  const [topic, setTopic] = useState('LangGraph'),
    [budget, setBudget] = useState(2),
    [id, setId] = useState(''),
    [run, setRun] = useState(null),
    [error, setError] = useState(''),
    [busy, setBusy] = useState(false)
  async function request(path, body) {
    setBusy(true)
    setError('')
    try {
      const response = await fetch(
        path,
        body
          ? {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(body),
            }
          : undefined,
      )
      const data = await response.json()
      if (!response.ok)
        throw new Error(typeof data.detail === 'string' ? data.detail : '输入不合法')
      setRun(data)
      setId(data.id)
    } catch (e) {
      setError(e.message)
    } finally {
      setBusy(false)
    }
  }
  const names = {
    waiting_approval: '等待你确认',
    done: '已保存',
    rejected: '已拒绝',
    cancelled: '已取消',
    budget_exhausted: '预算不足',
    no_evidence: '没有资料',
  }
  return (
    <main>
      <h1>有审批的研究助手</h1>
      <p>本地规则计划 · 真实 LangGraph 持久化 · 不调用模型</p>
      <label>
        主题 <input value={topic} onChange={(e) => setTopic(e.target.value)} />
      </label>
      <label>
        教学预算单位{' '}
        <input
          type="number"
          min="0"
          max="5"
          value={budget}
          onChange={(e) => setBudget(Number(e.target.value))}
        />
      </label>
      <button disabled={busy} onClick={() => request('/api/start', { topic, budget })}>
        开始研究
      </button>
      <label>
        任务编号（保存它可跨重启恢复）
        <input value={id} onChange={(e) => setId(e.target.value)} />
      </label>
      <button disabled={busy || !id} onClick={() => request(`/api/run/${encodeURIComponent(id)}`)}>
        读取任务
      </button>
      <p role="status">{busy ? '处理中' : error}</p>
      {run && (
        <section>
          <h2>{names[run.status] || run.status}</h2>
          <p>{run.draft}</p>
          <p>
            实际教学单位：{run.spent}；写入次数：{run.writes}
          </p>
          <ol>
            {run.trace?.map((s, i) => (
              <li key={i}>{s}</li>
            ))}
          </ol>
          <ul>
            {run.sources?.map((s) => (
              <li key={s}>
                <a href={s} target="_blank" rel="noreferrer">
                  核对来源：{s}
                </a>
              </li>
            ))}
          </ul>
          {run.status === 'waiting_approval' &&
            ['approve', 'reject', 'cancel'].map((action, i) => (
              <button
                key={action}
                disabled={busy}
                onClick={() => request('/api/decision', { id: run.id, action })}
              >
                {['批准并保存', '拒绝', '取消任务'][i]}
              </button>
            ))}
        </section>
      )}
    </main>
  )
}
createRoot(document.getElementById('root')).render(<App />)

from contextlib import closing
import sqlite3
from pathlib import Path
from typing import TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.types import interrupt, Command
from langgraph.checkpoint.sqlite import SqliteSaver


class State(TypedDict, total=False):
    id: str
    topic: str
    budget: int
    spent: int
    status: str
    sources: list
    draft: str
    trace: list
    writes: int


def build(saver, directory):
    def research(s):
        if s["budget"] < 1:
            return {
                "status": "budget_exhausted",
                "spent": 0,
                "trace": ["预算不足，未查询"],
                "sources": [],
            }
        catalog = {
            "Python": "https://docs.python.org/3/tutorial/",
            "LangGraph": "https://docs.langchain.com/oss/python/langgraph/overview",
        }
        url = catalog.get(s["topic"])
        if not url:
            return {
                "status": "no_evidence",
                "spent": 1,
                "trace": ["本地目录无结果"],
                "sources": [],
            }
        return {
            "status": "waiting_approval",
            "spent": 1,
            "sources": [url],
            "draft": f"阅读 {s['topic']} 官方入门并运行第一个例子",
            "trace": ["查询本地官方目录", "生成规则计划"],
        }

    def approval(s):
        decision = interrupt({"draft": s["draft"], "sources": s["sources"]})
        if decision not in ("approve", "reject", "cancel"):
            raise ValueError("未知决策")
        status = {"approve": "approved", "reject": "rejected", "cancel": "cancelled"}[
            decision
        ]
        return {"status": status, "trace": s["trace"] + [status]}

    def commit(s):
        with closing(sqlite3.connect(directory / "actions.db")) as db, db:
            db.execute(
                "CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY,draft TEXT)"
            )
            db.execute(
                "INSERT OR IGNORE INTO actions VALUES (?,?)", (s["id"], s["draft"])
            )
            count = db.execute(
                "SELECT count(*) FROM actions WHERE id=?", (s["id"],)
            ).fetchone()[0]
        return {"status": "done", "writes": count, "trace": s["trace"] + ["保存一次"]}

    graph = StateGraph(State)
    graph.add_node("research", research)
    graph.add_node("approval", approval)
    graph.add_node("commit", commit)
    graph.add_edge(START, "research")
    graph.add_conditional_edges(
        "research",
        lambda s: "approval" if s["status"] == "waiting_approval" else END,
        {"approval": "approval", END: END},
    )
    graph.add_conditional_edges(
        "approval",
        lambda s: "commit" if s["status"] == "approved" else END,
        {"commit": "commit", END: END},
    )
    graph.add_edge("commit", END)
    return graph.compile(checkpointer=saver)


def operate(directory, task_id, action, topic="LangGraph", budget=2):
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    config = {"configurable": {"thread_id": task_id}, "recursion_limit": 12}
    with SqliteSaver.from_conn_string(str(directory / "checkpoints.db")) as saver:
        graph = build(saver, directory)
        old = graph.get_state(config)
        if action == "start":
            if old.values:
                raise ValueError("任务已存在，请读取或继续")
            graph.invoke(
                {
                    "id": task_id,
                    "topic": topic,
                    "budget": budget,
                    "spent": 0,
                    "writes": 0,
                },
                config,
            )
        elif action in ("approve", "reject", "cancel"):
            if not old.values:
                raise ValueError("找不到任务")
            if old.next:
                graph.invoke(Command(resume=action), config)
        snapshot = graph.get_state(config)
        if not snapshot.values:
            raise ValueError("找不到任务")
        return dict(snapshot.values)

